    // V6.7: trascinamento di file e cartelle nella Gestione Diana Assistant\n    preLega();                         // V6.8: trascinamento di un documento sopra «Precompila con AI»\n    // V6.6: una foto di copertina che non si carica sparisce e torna il segnaposto col codice (l'evento error non risale: si ascolta in cattura)\n    r.addEventListener('error', function(e){\n      var t = e.target;\n      if(t && t.tagName === 'IMG' && t.classList && t.classList.contains('cop') && t.parentNode) t.parentNode.removeChild(t);\n    }, true);\n    document.addEventListener('keydown', onKey);\n    // i fogli dal basso (stato, notifiche) restano aperti anche se la pagina scorre (barra degli indirizzi del telefono)\n    window.addEventListener('scroll', function(){ if(openPopId && !(isPhone() && (openPopId === 'pop-state' || openPopId === 'pop-notif'))) closePops(); }, { passive:true });\n    window.addEventListener('hashchange', route);\n    var mq = window.matchMedia('(max-width:899px)');\n    var cambio = function(){ syncAcc(); if(!appEl.hidden) renderAuto(route); };       // V6.8.4: e' un cambio della finestra, non una scelta dell'agente: un campo di testo col fuoco non si ridisegna e la pagina non torna in cima\n    if(mq.addEventListener) mq.addEventListener('change', cambio); else if(mq.addListener) mq.addListener(cambio);\n    var attesa;\n    window.addEventListener('resize', function(){\n      if(!DOC.pdf || S.sec !== 'documenti' || S.sub !== 'compila') return;\n      // V6.8.4: si ridisegna SOLO se la larghezza del foglio (o la densita' dei pixel) e' davvero cambiata: la tastiera su schermo cambia l'altezza e basta\n      clearTimeout(attesa); attesa = setTimeout(function(){ if(cvServeRidisegno()) disegna(); }, 250);   // se l'agente gira il telefono la pagina va ridisegnata\n    });\n    // contatori ogni minuto (V6.6), solo a scheda visibile; e SUBITO quando arriva una notifica push (tc:push dal guscio, o il messaggio del service worker)\n    setInterval(tick, AG